using System;using System.Data;using System.Drawing;using System.Windows.Forms;using HRM.BUS;
namespace HRM{public class MainForm:Form{HRMBUS bus=new HRMBUS();TabControl tabs=new TabControl();DataGridView emp=new DataGridView(),dept=new DataGridView(),att=new DataGridView(),salary=new DataGridView();DateTimePicker month=new DateTimePicker();DataTable attendance;public MainForm(){Text="BÀI 6.2 - QUẢN LÝ NHÂN SỰ & TÍNH LƯƠNG";Width=1180;Height=760;StartPosition=FormStartPosition.CenterScreen;tabs.Dock=DockStyle.Fill;Controls.Add(tabs);BuildEmployees();BuildDepartments();BuildAttendance();BuildPayroll();}void Grid(DataGridView g,bool edit=false){g.Dock=DockStyle.Fill;g.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;g.SelectionMode=DataGridViewSelectionMode.FullRowSelect;g.MultiSelect=false;g.AllowUserToAddRows=false;g.ReadOnly=!edit;}void Error(Exception e){MessageBox.Show(e.Message,"Lỗi",MessageBoxButtons.OK,MessageBoxIcon.Error);}void BuildEmployees(){var p=new TabPage("Hồ sơ nhân viên");tabs.TabPages.Add(p);var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=45};var search=new TextBox{Width=220};var find=new Button{Text="Tìm tên / phòng ban / CCCD"};find.Click+=(s,e)=>{try{emp.DataSource=bus.Search(search.Text);}catch(Exception ex){Error(ex);}};var add=new Button{Text="Thêm nhân viên"};add.Click+=(s,e)=>EmployeeEdit(true);var edit=new Button{Text="Sửa / chuyển phòng"};edit.Click+=(s,e)=>EmployeeEdit(false);var del=new Button{Text="Xóa"};del.Click+=(s,e)=>DeleteEmployee();var reload=new Button{Text="Tải lại"};reload.Click+=(s,e)=>LoadEmployees();bar.Controls.AddRange(new Control[]{search,find,add,edit,del,reload});Grid(emp);p.Controls.Add(emp);p.Controls.Add(bar);LoadEmployees();}void LoadEmployees(){try{emp.DataSource=bus.Get("NhanVien");}catch(Exception ex){Error(ex);}}void EmployeeEdit(bool add){try{int id=0;string name="",cc="";DateTime dob=DateTime.Today;decimal sal=8000000;double factor=1;int pb=0;if(!add){if(emp.CurrentRow==null)return;var r=emp.CurrentRow;id=Convert.ToInt32(r.Cells["MaNV"].Value);name=Convert.ToString(r.Cells["HoTen"].Value);cc=Convert.ToString(r.Cells["CCCD"].Value);if(r.Cells["NgaySinh"].Value!=DBNull.Value)dob=Convert.ToDateTime(r.Cells["NgaySinh"].Value);sal=Convert.ToDecimal(r.Cells["LuongCoBan"].Value);factor=Convert.ToDouble(r.Cells["HeSoLuong"].Value);pb=Convert.ToInt32(r.Cells["MaPB"].Value);}using(var f=new EmployeeDialog(bus.Departments(),name,cc,dob,sal,factor,pb)){if(f.ShowDialog()==DialogResult.OK){if(add)bus.AddEmp(f.NameValue,f.Dob,f.CCCD,f.Department,f.Salary,f.Factor);else bus.UpdateEmp(id,f.NameValue,f.Dob,f.CCCD,f.Department,f.Salary,f.Factor);LoadEmployees();}}}catch(Exception ex){Error(ex);}}void DeleteEmployee(){try{if(emp.CurrentRow==null)return;int id=Convert.ToInt32(emp.CurrentRow.Cells["MaNV"].Value);if(MessageBox.Show("Xóa nhân viên này?","Xác nhận",MessageBoxButtons.YesNo)==DialogResult.Yes){bus.DeleteEmp(id);LoadEmployees();}}catch(Exception ex){Error(ex);}}
void BuildDepartments(){var p=new TabPage("Phòng ban");tabs.TabPages.Add(p);var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=45};var name=new TextBox{Width=180};name.Tag="Tên phòng ban";var desc=new TextBox{Width=220};desc.Tag="Mô tả";var add=new Button{Text="Thêm phòng ban"};add.Click+=(s,e)=>{try{if(string.IsNullOrWhiteSpace(name.Text))throw new Exception("Nhập tên phòng ban");bus.AddDept(name.Text,desc.Text);LoadDept();}catch(Exception ex){Error(ex);}};var del=new Button{Text="Xóa phòng ban"};del.Click+=(s,e)=>{try{if(dept.CurrentRow==null)return;int id=Convert.ToInt32(dept.CurrentRow.Cells["MaPB"].Value);bus.DeleteDept(id);LoadDept();}catch(Exception ex){Error(ex);}};bar.Controls.AddRange(new Control[]{name,desc,add,del});Grid(dept);p.Controls.Add(dept);p.Controls.Add(bar);LoadDept();}void LoadDept(){try{dept.DataSource=bus.Get("PhongBan");}catch(Exception ex){Error(ex);}}
void BuildAttendance(){var p=new TabPage("Chấm công (Disconnected)");tabs.TabPages.Add(p);var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=48};month.Format=DateTimePickerFormat.Custom;month.CustomFormat="MM/yyyy";month.ShowUpDown=true;var load=new Button{Text="Nạp chấm công"};load.Click+=(s,e)=>LoadAttendance();var save=new Button{Text="Lưu chấm công"};save.Click+=(s,e)=>SaveAttendance();var hint=new Label{Text="Nhập trực tiếp SoNgayCong và SoGioOT trên lưới",AutoSize=true,Padding=new Padding(8)};bar.Controls.AddRange(new Control[]{new Label{Text="Tháng/năm",AutoSize=true,Padding=new Padding(4)},month,load,save,hint});Grid(att,true);p.Controls.Add(att);p.Controls.Add(bar);LoadAttendance();}string MonthKey(){return month.Value.ToString("MM/yyyy");}void LoadAttendance(){try{attendance=bus.Attendance(MonthKey());att.DataSource=attendance;foreach(string col in new[]{"MaCong","MaNV","ThangNam"})if(att.Columns.Contains(col))att.Columns[col].ReadOnly=true;}catch(Exception ex){Error(ex);}}void SaveAttendance(){try{att.EndEdit();bus.SaveAttendance(attendance);MessageBox.Show("Đã lưu bảng chấm công bằng SqlDataAdapter.Update().");LoadAttendance();}catch(Exception ex){Error(ex);}}
void BuildPayroll(){var p=new TabPage("Tính lương / Chốt lương");tabs.TabPages.Add(p);var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=48};var close=new Button{Text="CHỐT LƯƠNG THÁNG",Width=180};close.Click+=(s,e)=>{try{if(MessageBox.Show("Chốt lương tháng "+MonthKey()+"? Sau khi chốt không thể sửa chấm công.","Xác nhận",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;bus.Payroll(MonthKey());salary.DataSource=bus.Salaries(MonthKey());MessageBox.Show("Chốt lương thành công.");}catch(Exception ex){Error(ex);}};var refresh=new Button{Text="Xem bảng lương"};refresh.Click+=(s,e)=>{try{salary.DataSource=bus.Salaries(MonthKey());}catch(Exception ex){Error(ex);}};bar.Controls.AddRange(new Control[]{new Label{Text="Dùng tháng/năm ở tab Chấm công",AutoSize=true,Padding=new Padding(5)},close,refresh});Grid(salary);p.Controls.Add(salary);p.Controls.Add(bar);}
}
public class EmployeeDialog:Form{public string NameValue,CCCD;public DateTime? Dob;public decimal Salary;public double Factor;public int Department;TextBox name=new TextBox(),cc=new TextBox(),sal=new TextBox(),factor=new TextBox();DateTimePicker dob=new DateTimePicker();ComboBox dep=new ComboBox();public EmployeeDialog(DataTable deps,string n,string c,DateTime d,decimal s,double h,int pb){Text="Thông tin nhân viên";Width=460;Height=390;StartPosition=FormStartPosition.CenterParent;var t=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,Padding=new Padding(12)};t.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,130));t.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));Controls.Add(t);dep.DropDownStyle=ComboBoxStyle.DropDownList;dep.DataSource=deps;dep.DisplayMember="TenPB";dep.ValueMember="MaPB";name.Text=n;cc.Text=c;dob.Format=DateTimePickerFormat.Short;dob.Value=d;sal.Text=s.ToString();factor.Text=h.ToString();foreach(var x in new Control[]{name,dob,cc,dep,sal,factor}){t.Controls.Add(new Label{Text=new[]{"Họ tên","Ngày sinh","CCCD","Phòng ban","Lương cơ bản","Hệ số lương"}[t.Controls.Count/2],AutoSize=true,Anchor=AnchorStyles.Left});t.Controls.Add(x);}if(pb>0)dep.SelectedValue=pb;var ok=new Button{Text="Lưu"};var cancel=new Button{Text="Hủy",DialogResult=DialogResult.Cancel};t.Controls.Add(ok);t.Controls.Add(cancel);ok.Click+=(a,b)=>{try{NameValue=name.Text.Trim();CCCD=cc.Text.Trim();if(NameValue==""||CCCD=="")throw new Exception("Nhập họ tên và CCCD");Dob=dob.Value;Department=Convert.ToInt32(dep.SelectedValue);Salary=decimal.Parse(sal.Text);Factor=double.Parse(factor.Text);if(Salary<=0||Factor<=0)throw new Exception("Lương và hệ số phải lớn hơn 0");DialogResult=DialogResult.OK;Close();}catch(Exception ex){MessageBox.Show(ex.Message);}};AcceptButton=ok;CancelButton=cancel;}}
}